pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C(100, "Test", "TST");
        // unfreeze the owner so they can burn
        vm.prank(address(c.owner()));
        c.freezeAccount(address(this), false);
    }

    function testFuzz_property(uint256 amount) public {
        // admissible domain: burn amount must be positive and not exceed owner's balance
        vm.assume(amount > 0);
        vm.assume(amount <= c.balanceOf(address(this)));

        uint256 supplyBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(address(this));

        vm.prank(address(this));
        c.burn(amount);

        uint256 supplyAfter = c.totalSupply();
        uint256 balAfter = c.balanceOf(address(this));

        // The reference C decreases totalSupply by exactly the burned amount.
        assertTrue(supplyAfter == supplyBefore - amount);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) {
        c = _c;
    }
    function test(address burner, uint256 amount) public returns (bool) {
        require(burner != address(0) && amount > 0);
        require(c.balanceOf(burner) >= amount);
        uint256 balBefore = c.balanceOf(burner);
        uint256 supplyBefore = c.totalSupply();
        (bool ok, ) = address(c).call(abi.encodeWithSignature("burn(uint256)", amount));
        require(ok);
        uint256 balAfter = c.balanceOf(burner);
        uint256 supplyAfter = c.totalSupply();
        assert(supplyBefore - supplyAfter == balBefore - balAfter);
    }
}

