pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 initialSupply, uint256 burnAmount, address caller) public {
        vm.assume(initialSupply > 0 && initialSupply < 1e40);
        vm.assume(burnAmount > 0 && burnAmount <= initialSupply);
        vm.assume(caller != address(0));

        // Deploy a fresh C with the fuzzed initial supply so the caller starts with the full supply
        c = new C(initialSupply, "Test", "TST");
        vm.prank(address(c).caller); // no-op, just to satisfy pattern
        vm.prank(c.owner());
        c.transfer(caller, initialSupply);

        uint256 balanceBefore = c.balanceOf(caller);
        uint256 totalBefore = c.totalSupply();

        vm.prank(caller);
        c.burn(burnAmount);

        uint256 balanceAfter = c.balanceOf(caller);
        uint256 totalAfter = c.totalSupply();

        // The rule: after burn, caller's balance must decrease by exactly burnAmount
        // This holds in the reference version; the buggy version does not decrement balanceOf
        assertTrue(balanceAfter == balanceBefore - burnAmount);
    }
}

