pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 burnAmount) public {
        // 1. Bound burnAmount to a wide admissible domain - must be <= total supply
        //    (the fuzzer will choose initial supply 0, so burn require can fail, but that's ok)
        //    We need to ensure the caller is the owner and the contract has enough balance
        //    We'll set up the initial state by minting tokens to the owner so burn is possible

        // Setup: give owner some balance to burn from
        address owner = address(this);
        vm.prank(owner);
        c.mintToken(owner, 1000);

        uint256 balanceBefore = c.balanceOf(owner);

        // Attempt burn as owner
        vm.prank(owner);
        try c.burn(burnAmount) {
            // Burn succeeded - check balance change
            uint256 balanceAfter = c.balanceOf(owner);

            // The property: balance should NOT increase after burn
            // Original: balance decreases, so balanceAfter <= balanceBefore always holds
            // Bug:    balance increases, so balanceAfter > balanceBefore for some burnAmount (<= initial balance)
            assertTrue(balanceAfter <= balanceBefore);
        } catch {
            // Burn reverted (e.g., burnAmount > balance). The property vacuously holds.
            // We don't need to check anything here.
        }
    }
}

