contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, "", ""); }
    function testFuzz_property(uint256 initialMint, uint256 burnAmount) public {
        // Restrict to reasonable ranges to avoid overflow issues, but keep wide enough
        initialMint = bound(initialMint, 1, type(uint128).max);
        burnAmount = bound(burnAmount, 1, initialMint);

        vm.startPrank(address(this));
        c.mintToken(address(this), initialMint);
        uint256 balanceBefore = c.balanceOf(address(this));
        c.burn(burnAmount);
        uint256 balanceAfter = c.balanceOf(address(this));
        uint256 totalSupplyAfter = c.totalSupply();
        vm.stopPrank();

        // General rule: after burning, the caller's balance must be ≤ balance before burn
        // AND totalSupply must equal (initialMint - burnAmount)
        // The mutant increases balance, so balanceAfter > balanceBefore breaks the rule
        assertTrue(balanceAfter <= balanceBefore && totalSupplyAfter == initialMint - burnAmount);
    }
}

