pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, "", ""); }
    function testFuzz_property(address burner, uint256 burnAmount, uint256 initialBalance) public {
        vm.assume(burner != address(0));
        // Give the burner some balance and ownership so they can burn
        vm.prank(address(this));
        c.mintToken(burner, initialBalance);
        vm.prank(address(this));
        c.transfer(address(0), 0); // no-op to ensure ownership is set; owner is this contract
        // Record initial balance
        uint256 balBefore = c.balanceOf(burner);
        // Attempt burn as burner
        vm.prank(burner);
        try c.burn(burnAmount) { } catch { }
        uint256 balAfter = c.balanceOf(burner);
        // For the reference (correct) contract, if burn succeeds, balAfter + burnAmount <= balBefore.
        // If burn reverts, balAfter == balBefore, so balAfter + burnAmount <= balBefore is false only when
        // burnAmount > 0 and initialBalance is insufficient, but the correct contract reverts, leaving balAfter == balBefore,
        // so balAfter + burnAmount > balBefore in that case would be true and the assertion would fail.
        // Actually, we assert that balAfter + burnAmount <= balBefore OR balAfter == balBefore for reverts.
        // Simpler: The reference always maintains balAfter + burnAmount <= balBefore || burn was not executed.
        // A precise invariant: balAfter + min(burnAmount, balBefore) >= balBefore (no). Let's state:
        // The reference contract ensures that the caller's balance cannot increase as a result of burn.
        // That is, balAfter <= balBefore.
        // The buggy version, when burnAmount > balBefore, underflows, making balAfter = 2^256 - (burnAmount - balBefore) which is huge, so balAfter > balBefore.
        assertTrue(balAfter <= balBefore, "burn should not increase balance");
    }
}

