pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 mintAmount, uint256 burnAmount) public {
        // Restrict to admissible domain: mintAmount and burnAmount can be any uint256;
        // but to have a non-trivial caller balance, we bound mint to avoid overflow in minting,
        // and ensure the sum does not overflow totalSupply.
        vm.assume(mintAmount <= type(uint256).max / 2);
        vm.assume(burnAmount <= type(uint256).max / 2);

        // Use the adversary: a reverter contract that always reverts on any call.
        // This is not required by the difference, but included to satisfy adversarial counterparty rule if needed.
        // Here we skip deploying a helper because the difference is purely internal state inconsistency.

        // Setup: give the test contract some tokens by minting to this address (onlyOwner)
        // The setUp deploys with owner = this test contract, so we can prank as owner.
        vm.deal(address(this), 0); 
        vm.prank(address(this));
        c.mintToken(address(this), mintAmount);

        uint256 callerBalBefore = c.balanceOf(address(this));
        uint256 totalSupplyBefore = c.totalSupply();

        // Prank the burn call as the owner (which is this contract) who holds tokens.
        vm.prank(address(this));
        // We attempt to burn; the reference will revert if burnAmount > callerBalBefore,
        // the mutant will not revert and corrupt state.
        bool ok = true;
        try c.burn(burnAmount) {} catch { ok = false; }

        if (ok) {
            // If the call succeeded, the invariant must hold.
            uint256 callerBalAfter = c.balanceOf(address(this));
            uint256 totalSupplyAfter = c.totalSupply();
            // Invariant: caller balance + totalSupply remains unchanged.
            assertTrue(callerBalBefore + totalSupplyBefore == callerBalAfter + totalSupplyAfter);
        } else {
            // If it reverts, state must be unchanged.
            assertTrue(c.balanceOf(address(this)) == callerBalBefore && c.totalSupply() == totalSupplyBefore);
        }
    }
}

