contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 burnAmount) public payable {
        require(burnAmount > 0 && c.balanceOf(address(this)) == 0);
        uint256 totalBefore = c.totalSupply();
        uint256 ownerBalanceBefore = c.balanceOf(address(c.owner()));
        c.burn(burnAmount);
        uint256 totalAfter = c.totalSupply();
        uint256 ownerBalanceAfter = c.balanceOf(address(c.owner()));
        // In original P, ownerBalance decreases by burnAmount, so totalAfter = sum of all balances.
        // In M, ownerBalance is unchanged, so totalAfter != sum of all balances (since owner balance unchanged, total decreased).
        // We observe: totalAfter == ownerBalanceAfter + address(this).balance (if we consider test contract's balance as a stand-in for other balances, which is 0 here).
        // More directly: In P: totalBefore - burnAmount == totalAfter AND ownerBalanceBefore - burnAmount == ownerBalanceAfter, so totalAfter == ownerBalanceAfter + (totalBefore - ownerBalanceBefore) + 0 (since other balances unchanged).
        // In M: ownerBalanceAfter == ownerBalanceBefore, but totalAfter == totalBefore - burnAmount, so totalAfter != ownerBalanceAfter + (totalBefore - ownerBalanceBefore).
        // So a rule that holds in P: totalSupply after burn == owner balance after burn + (initial totalSupply - initial owner balance).
        // This fails in M because owner balance unchanged.
        assert(totalAfter == ownerBalanceAfter + (totalBefore - ownerBalanceBefore));
    }
}

