        c.burn(burnAmount);

        // The correct contract unfroze the target (i.e., frozenAccount[target] is false),
        // enabling transfers; the buggy contract leaves it frozen (true), blocking transfers.
        // We verify by checking that a transfer from the target fails exactly when frozen.
        // Since the fuzzer supplies target, we can't transfer from target without its private key.
        // Instead, we assert the frozen state directly via the public getter.
        assertFalse(c.frozenAccount(target));
    }
}

