pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address target, bool freeze, uint256 burnAmount) public {
        // 1. Restrict domain: target cannot be the owner (owner can burn even when frozen)
        vm.assume(target != address(this));
        // Ensure target has enough balance to burn
        vm.assume(burnAmount > 0);
        // Ensure burnAmount is within a reasonable range for minting
        burnAmount = bound(burnAmount, 1, type(uint128).max);

        // 2. Setup: mint tokens to target so it has balance
        vm.prank(address(this));
        c.mintToken(target, burnAmount);

        // Owner freezes the target account
        vm.prank(address(this));
        c.freezeAccount(target, freeze);

        // 3. Target tries to burn its own tokens
        vm.prank(target);
        bool success = true;
        try c.burn(burnAmount) {
            success = true;
        } catch {
            success = false;
        }

        // 4. Assertion: if freeze is true, the burn must revert because account is frozen.
        // The reference correctly keeps the account frozen, so burn reverts.
        // The mutant always sets frozenAccount[target] = false, so burn succeeds.
        assertTrue(!freeze || !success);
    }
}

